set search_path = '';
select jsonb_build_object(
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'name',t.tgname,'function',format('%I.%I',fn.nspname,p.proname),'definition',pg_get_triggerdef(t.oid,false),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace fn on fn.oid=p.pronamespace where n.nspname in ('auth','storage') and fn.nspname in ('public','private') and not t.tgisinternal),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('relation',format('%I.%I',n.nspname,c.relname),'name',p.polname,'definition',format('CREATE POLICY %I ON %I.%I AS %s FOR %s TO %s%s%s',p.polname,n.nspname,c.relname,case when p.polpermissive then 'PERMISSIVE' else 'RESTRICTIVE' end,case p.polcmd when '*' then 'ALL' when 'r' then 'SELECT' when 'a' then 'INSERT' when 'w' then 'UPDATE' when 'd' then 'DELETE' end,(select string_agg(case when roleid=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(roleid)) end,', ' order by roleid) from unnest(p.polroles) roleid),case when p.polqual is null then '' else ' USING ('||pg_get_expr(p.polqual,p.polrelid)||')' end,case when p.polwithcheck is null then '' else ' WITH CHECK ('||pg_get_expr(p.polwithcheck,p.polrelid)||')' end)) order by n.nspname,c.relname,p.polname),'[]') from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('auth','storage'))
);
